os.listdir()
This function returns a list containing the names of the entries in the directory given by path.
The function name listdir() can be misleading; it doesn't list a directory; it lists everything in a directory (files & folders).
//+------------------------------------------------------------------+
//| Lists the entries contained in a directory.                      |
//|                                                                  |
//| The returned names are relative to the specified directory and   |
//| do not include the full path.                                    |
//|                                                                  |
//| parameters:                                                      |
//|   dirs  -  Output array receiving the entry names.               |
//|   path  -  Directory or wildcard path to search.                 |
//|            Defaults to "*" (parent directory).                   |
//|   folders_only - If true, only directories are returned.         |
//|                    If false, both files and directories are      |
//|                    returned.                                     |
//|   is_common_path  - Whether a folder is located in the common    |
//|                     folder or under Files.                       |
//+------------------------------------------------------------------+
void
COS::listdir(
string
&dirs[],
const
string
path =
"*"
,
bool
is_common_path =
false
)
  {
string
file_name;
//--- receive search handle in local folder's root
int
common_flag = is_common_path ?
FILE_COMMON
:
0
;
long
search_handle =
FileFindFirst
(path, file_name, common_flag);
int
found =
0
;
//--- check if FileFindFirst() function executed successfully
if
(search_handle !=
INVALID_HANDLE
)
     {
//--- check if the passed strings are file or directory names in the loop
do
{
ResetLastError
();
//--- if this is a file, the function will return true, if it is a directory, the function will generate error 5018
found++;
ArrayResize
(dirs, found);
         dirs[found -
1
] = file_name;
if
(
MQLInfoInteger
(
MQL_DEBUG
))
PrintFormat
(
"%d : %s"
, found, file_name);
        }
while
(
FileFindNext
(search_handle, file_name));
//--- close search handle
FileFindClose
(search_handle);
     }
  }
